import 'dart:convert';
import 'package:flutter/material.dart';

class DanaSeaLogo extends StatelessWidget {
  final double size;
  final BoxFit fit;

  const DanaSeaLogo({
    super.key,
    this.size = 28.0,
    this.fit = BoxFit.contain,
  });

  static const String _logoBase64 = '';

  @override
  Widget build(BuildContext context) {
    return Image.asset(
      'assets/danasea-logo.png',
      width: size,
      height: size,
      fit: fit,
      errorBuilder: (context, error, stackTrace) {
        return Image.memory(
          base64Decode(_logoBase64),
          width: size,
          height: size,
          fit: fit,
        );
      },
    );
  }
}
